def filter_api_calls(with_result, call_only, no_call, tau_filter):
    # Validate inputs
    if isinstance(tau_filter, bool):
        raise ValueError("Invalid threshold: boolean values are not allowed")
    if not np.isfinite(tau_filter) or tau_filter < 0:
        raise ValueError("Invalid threshold: must be finite nonnegative")

    for name, arr in [("with_result", with_result), ("call_only", call_only), ("no_call", no_call)]:
