        if arr.shape[0] == 0 or arr.shape[1] == 0:
            raise ValueError(f"{name} cannot be empty")
        if not np.all(np.isfinite(arr)):
            raise ValueError(f"{name} contains nonfinite values")
        if not np.all(arr <= 0):
            raise ValueError(f"{name} contains positive values")

    if not (with_result.shape == call_only.shape == no_call.shape):
        raise ValueError("All input matrices must have the same shape")

    n_candidates, horizon = with_result.shape

    # Compute normalized weights
    t = np.arange(horizon, dtype=float)
    raw_weights = np.maximum(0.0, 1.0 - 0.2 * t)
    weight_sum = raw_weights.sum()
    if weight_sum == 0:
        normalized_weights = np.zeros(horizon)
    else:
        normalized_weights = raw_weights / weight_sum

    # Compute weighted losses: -sum(w * log_prob)
    loss_plus = -np.sum(normalized_weights * with_result, axis=1)
    loss_call_only = -np.sum(normalized_weights * call_only, axis=1)
    loss_no_call = -np.sum(normalized_weights * no_call, axis=1)

    # L_minus = min(L_empty, L_call_only)
    L_minus = np.minimum(loss_no_call, loss_call_only)

    margins = L_minus - loss_plus
    keep = margins >= tau_filter

    return keep, margins
